import React, { useCallback } from 'react';
import { SearchEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID, VIEWPORT_LESS_TOP_HEADER } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const DARK = '#0C0C0C';
const BRAND_GREEN = '#22D472';

export default function SearchPage() {
  const { hiddenActions, disabledActions } = useTier();

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Search]', formatThoughtSpotEmbedError(err), err);
  }, []);

  return (
    <div
      style={{
        height: VIEWPORT_LESS_TOP_HEADER,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: DARK,
        overflow: 'hidden',
        minHeight: 0,
      }}
    >
      <div style={{ padding: '1.75rem 2.5rem 1.5rem', backgroundColor: DARK, flexShrink: 0 }}>
        <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase', color: BRAND_GREEN, marginBottom: 6 }}>VisioLab</div>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#ffffff', margin: 0, letterSpacing: '-0.03em' }}>Style Search</h1>
        <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.55)', margin: '6px 0 0' }}>
          Search your retail data with guided tokens and filters.
        </p>
      </div>

      <div style={{ padding: '0.5rem 2.5rem 1.25rem', flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
        <div
          style={{
            flex: 1,
            minHeight: 0,
            backgroundColor: '#ffffff',
            borderRadius: 16,
            border: 'none',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column',
            boxShadow: '0 2px 32px rgba(0,0,0,0.5)',
          }}
        >
          <SearchEmbed
            dataSource={THOUGHTSPOT_MODEL_ID}
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            onError={onError}
            style={{ width: '100%', height: '100%', flex: 1, minHeight: 0, border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
